<?php
namespace SenderSuite;

final class Passwords {
    public function hash($plain) { if(!defined('PASSWORD_ARGON2ID')||!in_array('argon2id',password_algos(),true)){throw new \RuntimeException('Native Argon2id is required.');}$hash=password_hash($plain,PASSWORD_ARGON2ID,array('memory_cost'=>65536,'time_cost'=>3,'threads'=>4));if($hash===false){throw new \RuntimeException('Password hashing failed.');}return $hash; }
    public function verify($plain,$hash) {return is_string($hash)&&preg_match('/^\$argon2(?:id|i|d)\$/',$hash)===1&&password_verify($plain,$hash);}
}
final class Tokens {
    private $key;private $minutes;
    public function __construct($key,$minutes=1440) {if(!is_string($key)||strlen($key)<32){throw new \InvalidArgumentException('A protected signing key is required.');}$this->key=$key;$this->minutes=$minutes;}
    private static function encode($s){return rtrim(strtr(base64_encode($s),'+/','-_'),'=');}
    private static function decode($s){if(!is_string($s)||!preg_match('/^[A-Za-z0-9_-]+$/D',$s)){return false;}return base64_decode(strtr($s,'-_','+/').str_repeat('=',(4-strlen($s)%4)%4),true);}
    public function sign(array $claims,$now=null) { $now=$now??time();$claims['exp']=$now+$this->minutes*60;$header=self::encode('{"alg":"HS256","typ":"JWT"}');$body=self::encode(json_encode($claims,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$data=$header.'.'.$body;return $data.'.'.self::encode(hash_hmac('sha256',$data,$this->key,true)); }
    public function verify($token,$now=null) {try{if(!is_string($token)||strlen($token)>16384){return null;}$parts=explode('.',$token);if(count($parts)!==3){return null;}list($h,$b,$s)=$parts;$sig=self::decode($s);if($sig===false||!hash_equals(hash_hmac('sha256',$h.'.'.$b,$this->key,true),$sig)){return null;}$header=json_decode(self::decode($h),true,512,JSON_THROW_ON_ERROR);$claims=json_decode(self::decode($b),false,512,JSON_THROW_ON_ERROR);if(($header['alg']??null)!=='HS256'||!is_object($claims)||!isset($claims->exp)||!is_int($claims->exp)){return null;}$now=$now??time();if($claims->exp<$now||isset($claims->aud)||(isset($claims->nbf)&&(!is_int($claims->nbf)||$claims->nbf>$now))||(isset($claims->sub)&&!is_string($claims->sub))||(isset($claims->jti)&&!is_string($claims->jti))){return null;}return (array)$claims;}catch(\Throwable $e){return null;} }
    public function __debugInfo(){return array('key'=>'[redacted]');}public function __serialize(){throw new \RuntimeException('Token signer serialization forbidden.');}public function __sleep(){throw new \RuntimeException('Token signer serialization forbidden.');}
