/** Own-application accounts, never WordPress administrator identity. Codec injection is for offline tests only. */
final class AppAuth {
    private $db;private $config;private $passwords;private $clock;
    public function __construct(Database $db,Config $config,$passwords=null,callable $clock=null){$this->db=$db;$this->config=$config;$this->passwords=$passwords??new Passwords();$this->clock=$clock??function(){return (new \DateTimeImmutable('now',new \DateTimeZone('UTC')))->format('Y-m-d H:i:s.u');};}
    private function now(){return ($this->clock)();}
    public function siteHash(){$value=$this->db->one('system_settings',array('key'=>'auth.password_hash'))['value']??null;return $value===null||$value===''?null:$value;}
    private function accepted(){ $admin=Compat::strip($this->config->get('ADMIN_PASSWORD')??'');$legacy=Compat::strip($this->config->get('LOGIN_PASSWORD')??'');return $admin!==''?array($admin):($legacy!==''?array($legacy):array()); }
    public function access(){ $admin=Compat::strip($this->config->get('ADMIN_PASSWORD')??'');$legacy=$admin===''&&Compat::strip($this->config->get('LOGIN_PASSWORD')??'')!=='';$site=$this->siteHash();$source=$admin!==''?'admin':($site!==null?'site':($legacy?'legacy':'none'));return array('password_required'=>$admin!==''||$legacy||$site!==null,'password_set'=>$site!==null,'source'=>$source,'hint'=>$source==='admin'?'Enter the admin password for this deployment.':($source==='site'?'Enter the password saved in Settings → Site access.':($source==='legacy'?"Enter this deployment's login password.":''))); }
    private function admin(){ $name=$this->config->get('ADMIN_USERNAME');$user=$this->db->one('users',array('username'=>$name));$now=$this->now();if($user===null){$id=$this->db->insert('users',array('username'=>$name,'password_hash'=>$this->passwords->hash($this->config->get('ADMIN_PASSWORD')??''),'display_name'=>'Administrator','role'=>'admin','is_active'=>true,'created_at'=>$now,'updated_at'=>$now));$user=$this->db->one('users',array('id'=>$id));} $changes=array();if(!$user['is_active']){$changes['is_active']=true;}if(!$this->passwords->verify($this->config->get('ADMIN_PASSWORD')??'',$user['password_hash'])){$changes['password_hash']=$this->passwords->hash($this->config->get('ADMIN_PASSWORD')??'');}if($changes){$changes['updated_at']=$now;$this->db->update('users',$changes,array('id'=>$user['id']));$user=array_merge($user,$changes);}return $user; }
    public function authenticate($username,$password){return $this->db->transaction(function()use($username,$password){$candidate=Compat::strip($password??'');if($candidate===''){return $this->access()['password_required']?null:$this->admin();}$name=Compat::strip($username??'');if($name===''){$name=$this->config->get('ADMIN_USERNAME');}$user=$name===$this->config->get('ADMIN_USERNAME')?$this->admin():$this->db->one('users',array('username'=>$name));$accepted=false;foreach($this->accepted() as $expected){if(hash_equals($expected,$candidate)){$accepted=true;}}if($accepted){if($user!==null&&$user['is_active']){if($user['username']===$this->config->get('ADMIN_USERNAME')&&!$this->passwords->verify($candidate,$user['password_hash'])){$user['password_hash']=$this->passwords->hash($candidate);$this->db->update('users',array('password_hash'=>$user['password_hash'],'updated_at'=>$this->now()),array('id'=>$user['id']));}return $user;}return $this->admin();}if($user!==null&&$user['is_active']&&$this->passwords->verify($candidate,$user['password_hash'])){return $user;}$site=$this->siteHash();return $site&&$this->passwords->verify($candidate,$site)?$this->admin():null;}); }
    public function current($cookie){if(!$cookie){return null;}$claims=(new Tokens($this->config->get('SECRET_KEY'),$this->config->get('ACCESS_TOKEN_EXPIRE_MINUTES')))->verify($cookie);$sub=$claims['sub']??null;if(!is_string($sub)||!preg_match('/^[0-9]+$/D',$sub)||strlen($sub)>10){return null;}$user=$this->db->one('users',array('id'=>(int)$sub));return $user!==null&&$user['is_active']?$user:null;}
    public function signIn(array $user){$this->db->update('users',array('last_login'=>$this->now(),'updated_at'=>$this->now()),array('id'=>$user['id']));$token=(new Tokens($this->config->get('SECRET_KEY'),$this->config->get('ACCESS_TOKEN_EXPIRE_MINUTES')))->sign(array('sub'=>(string)$user['id'],'role'=>$user['role']));return array('token'=>$token,'body'=>array('success'=>true,'user_id'=>$user['id'],'username'=>$user['username'],'role'=>$user['role'],'message'=>'Login successful'));}
    public static function userOut(array $user){return array_intersect_key($user,array_flip(array('id','username','display_name','role','is_active')));}
}
